sources.EditPanel.ets:
@Component
export struct EditPanel {
  @State expanded: boolean = false;
  @Builder
  renderDetails() {
    Row() {
      SymbolGlyph('arrow').rotate({ angle: this.expanded ? 0 : 180 });
    }.onClick(() => {
      this.expanded = !this.expanded;
    });
  }
  build() { this.renderDetails(); }
}

sources.SplitPanel.ets:
@Component
export struct SplitPanel {
  @State displayed: boolean = false;
  @State selected: boolean = false;
  @Builder
  renderDetails() {
    Row() {
      SymbolGlyph('arrow').rotate({ angle: this.displayed ? 0 : 180 });
    }.onClick(() => {
      this.selected = !this.selected;
    });
  }
  build() { this.renderDetails(); }
}

